const FALLBACK_SUPABASE_URL = "https://placeholder.invalid";
const FALLBACK_SUPABASE_PUBLISHABLE_KEY = "development-placeholder-key";

function readEnv(name: string): string {
  const value = import.meta.env[name];
  return typeof value === "string" ? value.trim() : "";
}

function readBool(name: string): boolean {
  const v = readEnv(name).toLowerCase();
  return v === "true" || v === "1";
}

export type SupabaseProjectConfig = {
  id: "primary" | "secondary";
  url: string;
  publishableKey: string;
};

export function getRuntimeConfig() {
  const supabaseUrl = readEnv("VITE_SUPABASE_URL");
  const supabasePublishableKey =
    readEnv("VITE_SUPABASE_PUBLISHABLE_KEY") || readEnv("VITE_SUPABASE_ANON_KEY");
  const secondaryUrl = readEnv("VITE_SUPABASE_URL_SECONDARY");
  const secondaryKey =
    readEnv("VITE_SUPABASE_PUBLISHABLE_KEY_SECONDARY") ||
    readEnv("VITE_SUPABASE_ANON_KEY_SECONDARY");
  const missingSupabaseConfig = !supabaseUrl || !supabasePublishableKey;

  const projects: SupabaseProjectConfig[] = [];
  if (supabaseUrl && supabasePublishableKey) {
    projects.push({ id: "primary", url: supabaseUrl, publishableKey: supabasePublishableKey });
  }
  if (secondaryUrl && secondaryKey) {
    projects.push({ id: "secondary", url: secondaryUrl, publishableKey: secondaryKey });
  }

  return {
    supabaseUrl: supabaseUrl || FALLBACK_SUPABASE_URL,
    supabasePublishableKey: supabasePublishableKey || FALLBACK_SUPABASE_PUBLISHABLE_KEY,
    secondarySupabaseUrl: secondaryUrl,
    secondarySupabasePublishableKey: secondaryKey,
    projects,
    hasFailover: projects.length > 1,
    missingSupabaseConfig,
    feedBackend: readEnv("VITE_FEED_BACKEND") || (readBool("VITE_USE_TURSO_FEEDS") ? "turso" : "supabase"),
    corsProxyUrl: readEnv("VITE_CORS_PROXY_URL"),
    freeStoragePolicy: readEnv("VITE_FREE_STORAGE_POLICY") || "free-first",
  };
}

/** Ordered project list for health probes / edge-function failover. */
export function getSupabaseProjects(): SupabaseProjectConfig[] {
  return getRuntimeConfig().projects;
}
